// ─────────────────────────────────────────────────────────────────────────
// 게이트 + 프롬프트 렌더링
// 실행 모드: Run Once for Each Item
//
// 게이트가 AI 호출 **전에** 다이제스트를 거른다. collector 로 보내봤자
// 이미 콜을 쓴 뒤다.
//
// 프롬프트와 digest_tags 는 「GET prompt」 에서 한 번 받은 것을 참조한다.
// 여기에 배열을 다시 쓰면 정본이 둘이 된다.
// ─────────────────────────────────────────────────────────────────────────

const P = $('GET prompt').first().json;
const TAGS = new Set((P.gate && P.gate.digest_tags) || []);

// ── 게이트 ──────────────────────────────────────────────────────────────
// 제목 **맨 앞**의 【태그】만 본다. 중간에 인용된 【】는 게이트가 아니다.
// 모르는 태그는 통과시키고 경고만 남긴다 — 잘못 거르면 기사가 통째로
// 사라지지만, 잘못 통과시키면 분류가 이상해질 뿐이다.
const m = String($json.title || '').trim().match(/^【([^】]+)】/);
const tag = m ? m[1].trim().replace(/\s+/g, ' ') : null;
const isDigest = tag !== null && TAGS.has(tag);

// ── 렌더링 ──────────────────────────────────────────────────────────────
// 한 번의 정규식 치환으로 처리한다. 순차 치환하면 기사 제목에 다른
// 자리표시자 문자열이 들어 있을 때 재치환된다.
const VALUES = {
  PRESS: $json.press ?? '',
  PUBLISHED_AT: $json.published_at ?? '',
  TITLE: $json.title ?? '',
  CLASSIFICATION_TEXT: $json.classification_text ?? '',
};
const TOKEN = /\[\[([A-Z_]+)\]\]/g;

let userPrompt = null;
if (!isDigest) {
  // 렌더링 **전에** 필수 토큰이 정확히 한 번씩 있는지 검증한다
  const counts = {};
  for (const t of P.user_template.matchAll(TOKEN)) {
    counts[t[1]] = (counts[t[1]] || 0) + 1;
  }
  for (const k of Object.keys(VALUES)) {
    if (counts[k] !== 1) {
      throw new Error(`user_template 의 [[${k}]] 가 ${counts[k] || 0}번 — 정확히 1번이어야 한다`);
    }
  }
  const unknown = Object.keys(counts).filter((k) => !(k in VALUES));
  if (unknown.length) {
    throw new Error(`user_template 에 모르는 자리표시자: ${unknown.join(', ')}`);
  }
  userPrompt = P.user_template.replace(TOKEN, (whole, key) =>
    key in VALUES ? VALUES[key] : whole);
}

return {
  json: {
    article_id: $json.id,
    press: $json.press,
    title: $json.title,
    gate_result: isDigest ? 'digest' : 'pass',
    digest_tag: isDigest ? tag : null,
    unknown_tag: (!isDigest && tag) ? tag : null,   // 경고. 요약이 센다
    prompt_version: P.version,
    prompt_sha256: P.sha256,
    system_prompt: isDigest ? null : P.system_prompt,
    user_prompt: userPrompt,
  },
};

// ─────────────────────────────────────────────────────────────────────────
// 분류 출력 검증 — LLM 응답을 POST /articles/classify 요청 본문으로
// 실행 모드: Run Once for Each Item
//
// 여기서 하는 건 **형식 검증**뿐이다. subject_id 가 실제로 존재하는지,
// 이름이 정본과 맞는지는 collector 가 subjects 조회로 판단한다(결정 #99).
// id 범위(1~13)를 여기 쓰면 subject 개수가 사는 곳이 하나 더 생긴다.
// ─────────────────────────────────────────────────────────────────────────

const src = $('게이트·렌더링').item.json;

// 에이전트 에러 아이템 (onError: continueRegularOutput)
if ($json.error !== undefined) {
  const e = $json.error;
  return { json: {
    __skip: true,
    article_id: src.article_id,
    title: src.title,
    reject: 'agent_error',
    detail: String((e && (e.message || e.description)) || e).slice(0, 200),
  }};
}

const out = $json.output ?? $json;

function fail(reject, detail) {
  return { json: { __skip: true, article_id: src.article_id,
                   title: src.title, reject, detail } };
}

if (out === null || typeof out !== 'object') return fail('not_an_object', typeof out);

const state = out.mapping_state;
if (state !== 'mapped' && state !== 'mapping_failed') {
  return fail('bad_mapping_state', String(state).slice(0, 60));
}

let subjectId = out.subject_id;
if (state === 'mapped') {
  if (!Number.isInteger(subjectId)) {
    return fail('subject_id_not_integer', String(subjectId).slice(0, 60));
  }
} else {
  // mapping_failed 는 subject_id=null 이 정상이다 — subjects 목록의
  // 공백을 찾는 신호라, 형식 오류와 섞으면 그 신호가 죽는다
  subjectId = null;
}

const reason = typeof out.reason === 'string' ? out.reason.trim().slice(0, 200) : null;
const name = typeof out.subject_name === 'string' && out.subject_name.trim()
  ? out.subject_name.trim() : null;

return { json: {
  article_id: src.article_id,
  gate_result: 'pass',
  subject_id: subjectId,
  // 이름은 검증용으로만 보낸다. 정본은 subjects 테이블이고, 불일치는
  // collector 가 422 로 막는다 — 경계표에 뭘 추가할지 알려주는 재료다
  subject_name: state === 'mapped' ? name : null,
  reason,
  _title: src.title,
}};

// ─────────────────────────────────────────────────────────────────────────
// 분류 요약 — 상위 워크플로(wf_daily)가 완료를 읽는 단일 지점
// 실행 모드: Run Once for All Items
//
// pending 0건이면 「기사별로 분리」에서 흐름이 끊긴다. 앞에서 명시적으로
// 분기해 이리로 보낸다 — 항상 정확히 한 건이 나와야 상위가 완료를 읽는다.
//
// 실패를 조용히 버리지 않는다. 형식 검증에서 걸린 것(__skip)과 collector 가
// 거부한 것(422·409)을 따로 센다. 원인이 다른 것을 같은 신호로 만들지 않는다.
//
// **앞에 Merge 가 필요하다.** n8n 은 한 노드의 같은 입력에 여러 연결이
// 들어오면 브랜치마다 한 번씩 실행한다. 네 갈래(pending 0건 · POST classify ·
// POST digest · 검증 실패)를 바로 물리면 요약이 여러 번 나오고,
// "상위가 완료를 읽는 단일 지점"이라는 전제가 깨진다.
// ─────────────────────────────────────────────────────────────────────────

const items = $input.all().map(i => i.json || {});
const zero = items.find(j => j.__zero_pending === true);
const rows = items.filter(j => !j.__zero_pending);

let pending = 0;
try { pending = $('GET pending').first().json.count || 0; }
catch (e) { pending = zero ? 0 : rows.length; }

const count = (fn) => rows.filter(fn).length;
const tally = (fn, key) => {
  const t = {};
  for (const r of rows) if (fn(r)) { const k = r[key]; if (k) t[k] = (t[k] || 0) + 1; }
  return t;
};

// collector 응답: result = applied | already_applied
// 거부: detail.error = invalid_classification | result_conflict
const applied = count(r => r.result === 'applied');
const already = count(r => r.result === 'already_applied');
// 판정 내역은 서로 겹치지 않게 센다. digest 응답도 result='applied' 라
// applied 안에 포함된다 — mapped + mapping_failed + digest = applied
const digest  = count(r => r.state === 'excluded' && r.state_reason === 'digest');
const mapped  = count(r => r.primary_subject_id != null);
const failed  = count(r => r.state_reason === 'subject_mapping_failed');

const rejected = rows.filter(r => r.detail && r.detail.error);
const skipped  = rows.filter(r => r.__skip === true);

return [{
  json: {
    stage: 'classify',
    ok: rejected.length === 0 && skipped.length === 0,
    pending_articles: pending,
    processed: rows.length,
    applied,
    already_applied: already,
    // 판정 내역
    mapped,
    mapping_failed: failed,
    digest,
    // 실패 — 원인별로 가른다
    format_rejected: skipped.length,          // 형식 검증에서 걸림
    collector_rejected: rejected.length,      // 422 · 409
    format_reasons: (() => {
      const t = {}; for (const r of skipped) { const k = r.reject || 'unknown'; t[k] = (t[k]||0)+1; } return t;
    })(),
    collector_reasons: (() => {
      const t = {}; for (const r of rejected) { const k = r.detail.error; t[k] = (t[k]||0)+1; } return t;
    })(),
    // 모르는 【태그】 — 다음 튜닝 근거
    unknown_tags: (() => {
      const t = {};
      try {
        for (const it of $('게이트·렌더링').all()) {
          const k = it.json.unknown_tag; if (k) t[k] = (t[k]||0)+1;
        }
      } catch (e) {}
      return t;
    })(),
    finished_at: new Date().toISOString().replace(/\.\d{3}Z$/, 'Z'),
  },
}];
